                  })}
                  {field("city", "Cidade")}
                  {field("state", "Estado")}
                  <Choices
                    label="Gênero (opcional)"
                    value={form.gender}
                    options={[
                      "Não informar",
                      "Feminino",
                      "Masculino",
                      "Outro",
                    ].map((value) => ({ value, label: value }))}
                    onChange={(value) =>
                      setForm({
