                <View
                  style={{
                    height: 6,
                    width: `${(step + 1) * 20}%`,
                    backgroundColor: "#D4142C",
                    borderRadius: 4,
                  }}
                />
              </View>
            </Card>
            <Card>
              {step === 0 && (
