                  })}
                  {field("email", "E-mail *", {
                    keyboardType: "email-address",
                    autoCapitalize: "none",
                    autoComplete: "email",
                  })}
                  {field("phone", "WhatsApp *", {
                    keyboardType: "phone-pad",
                    placeholder: "DDD + número",
                  })}
                  {field("city", "Cidade")}
                  {field("state", "Estado")}
                  <Choices
                    label="Gênero (opcional)"
                    value={form.gender}
                    options={[
                      "Não informar",
                      "Feminino",
                      "Masculino",
                      "Outro",
                    ].map((value) => ({ value, label: value }))}
                    onChange={(value) =>
                      setForm({
                        ...form,
                        gender: value as EnrollmentInput["gender"],
                      })
                    }
                  />
                </>
              )}
              {step === 1 && (
                <>
                  <Label size={20} bold>
                    Qual é seu principal objetivo?
                  </Label>
                  <Label muted>Você pode selecionar mais de uma opção.</Label>
                  {enrollmentGoals.map((goal) => (
                    <Check
                      key={goal}
                      label={goal}
                      checked={form.goals.includes(goal)}
                      onChange={() =>
                        setForm({
                          ...form,
                          goals: form.goals.includes(goal)
                            ? form.goals.filter((x) => x !== goal)
                            : [...form.goals, goal],
                        })
                      }
                    />
                  ))}
                  {field("specificGoals", "Objetivos específicos", {
                    multiline: true,
                  })}
                </>
              )}
              {step === 2 && (
                <>
                  {(["practicing", "previousTrainer"] as const).map(
                    (key, i) => (
                      <Choices
                        key={key}
