            fontSize: 11,
            fontWeight: "700",
            letterSpacing: 2,
          }}
        >
          TÁ PAGO PERSONAL
        </Text>
        <Text
          style={{
            color: "#fff",
            fontSize: 32,
            lineHeight: 39,
            fontWeight: "700",
            marginVertical: 16,
          }}
