export function ChainIcon() {
  const theme = useTheme();
  return (
    <View
      accessibilityRole="image"
      accessibilityLabel="Link de compartilhamento"
      style={{ width: 48, height: 48, marginBottom: 12 }}
    >
      {[0, 1].map((i) => (
        <View
          key={i}
          style={{
            position: "absolute",
            left: 4 + i * 13,
            top: 10 + i * 12,
            width: 29,
            height: 16,
            borderWidth: 3,
            borderColor: theme.accent,
            borderRadius: 9,
            transform: [{ rotate: "-45deg" }],
          }}
        />
      ))}
    </View>
  );
}

