export function Check({
  label,
  checked,
  onChange,
}: {
  label: string;
  checked: boolean;
  onChange: () => void;
}) {
  const theme = useTheme();
  return (
    <Pressable
      accessibilityRole="checkbox"
      accessibilityLabel={label}
      accessibilityState={{ checked }}
      onPress={onChange}
      style={[
        s.row,
        {
          padding: 12,
          marginBottom: 8,
          borderWidth: 1,
          borderColor: checked ? theme.accent : theme.border,
          borderRadius: 10,
        },
      ]}
    >
      <View
        style={{
          width: 20,
          height: 20,
          borderWidth: 2,
          borderColor: checked ? theme.accent : theme.border,
          borderRadius: 4,
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {checked && (
          <View
            style={{
              width: 7,
              height: 12,
              borderRightWidth: 2,
              borderBottomWidth: 2,
              borderColor: theme.accent,
              transform: [{ rotate: "45deg" }],
              marginTop: -3,
            }}
          />
        )}
      </View>
      <View style={{ flex: 1 }}>
        <Label>{label}</Label>
      </View>
    </Pressable>
  );
}

