function RecordValues({ record: r }: { record: TrackingRecord }) {
  return (
    <View style={s.grid}>
      {recordFields[r.kind].map((f) =>
        r.data[f.key] !== null &&
        r.data[f.key] !== "" &&
        r.data[f.key] !== undefined ? (
          <View
            key={f.key}
            style={{ minWidth: 130, flexGrow: 1, marginBottom: 8 }}
          >
            <Label size={11} muted>
              {f.label}
            </Label>
            <Label>{String(r.data[f.key])}</Label>
          </View>
        ) : null,
      )}
      {r.kind === "monthly" && (
        <View>
          <Label size={11} muted>
            Adesão
          </Label>
          <Label>
