            router.replace((studentView ? "/" : "/alunos") as Href)
          }
        >
          Voltar
        </Button>
      </Page>
    );
  const lastMonthly = student.records.find((r) => r.kind === "monthly");
  const lastEvaluation = student.evaluations.find(
    (e) => e.status === "concluida",
  );
