export function PersonalShell({ children }: { children: ReactNode }) {
  const t = useTheme();
  const { user, logout } = useSession();
  const [error, setError] = useState("");
  const { width } = useWindowDimensions();
  if (!user)
    return (
      <View style={{ flex: 1, backgroundColor: t.backgroundElement }}>
        {children}
      </View>
    );
  return (
    <SafeAreaView style={{ flex: 1, backgroundColor: t.backgroundElement }}>
      <View
        style={[
          styles.header,
          { backgroundColor: t.background, borderColor: t.border },
        ]}
      >
        <View style={[styles.headerInner, { gap: width < 700 ? 14 : 24 }]}>
          <Brand />
          {width >= 900 && <AppTabs />}
          <View style={[s.row, { marginLeft: width >= 700 ? "auto" : 0 }]}>
            <View>
              <Label size={12} bold>
                {user.name}
              </Label>
              <Label size={10} muted>
                {user.role === "personal"
                  ? "Conta profissional"
                  : "Conta do aluno"}
              </Label>
            </View>
            <Button
              variant="secondary"
              onPress={async () => {
                try {
                  await logout();
                } catch (e) {
                  setError(message(e));
                }
              }}
            >
              Sair
            </Button>
          </View>
          {width < 900 && <AppTabs />}
        </View>
      </View>
      <Notice error>{error}</Notice>
      <View style={{ flex: 1 }}>{children}</View>
    </SafeAreaView>
  );
}

